class Solution:
    def totalHammingDistance(self, nums: list[int]) -> int:
        n=len(nums);total=0
        for bit in range(32):
            ones=sum((x>>bit)&1 for x in nums);total+=ones*(n-ones)
        return total

class Solution {
    public int totalHammingDistance(int[] nums) {
        long total=0;int n=nums.length;
        for(int b=0;b<32;b++){int ones=0;for(int x:nums)ones+=(x>>>b)&1;total+=(long)ones*(n-ones);}
        return (int)total;
    }
}

