class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        chars=[c.upper() for c in s if c!='-'];groups=[]
        while chars:
            groups.append(''.join(chars[-k:]));chars=chars[:-k]
        return '-'.join(reversed(groups))

class Solution {
    public String licenseKeyFormatting(String s,int k) {
        String clean=s.replace("-","").toUpperCase(Locale.ROOT);StringBuilder out=new StringBuilder();int count=0;
        for(int i=clean.length()-1;i>=0;i--){if(count==k){out.append('-');count=0;}out.append(clean.charAt(i));count++;}
        return out.reverse().toString();
    }
}

class Solution:
    def findMaxConsecutiveOnes(self, nums: list[int]) -> int:
        curr=best=0
        for x in nums:
            if x==1:curr+=1;best=max(best,curr)
            else:curr=0
        return best

class Solution {
    public int findMaxConsecutiveOnes(int[] nums) {
        int curr=0,best=0;for(int x:nums){if(x==1){curr++;best=Math.max(best,curr);}else curr=0;}return best;
    }
}

class Solution:
    def PredictTheWinner(self, nums: list[int]) -> bool:
        n=len(nums);dp=nums[:]
        for length in range(2,n+1):
            for i in range(n-length+1):
                j=i+length-1
                dp[i]=max(nums[i]-dp[i+1],nums[j]-dp[i])
        return dp[0]>=0

class Solution {
    public boolean PredictTheWinner(int[] nums) {
        int n=nums.length;int[]dp=nums.clone();
        for(int len=2;len<=n;len++)for(int i=0;i+len<=n;i++){int j=i+len-1;dp[i]=Math.max(nums[i]-dp[i+1],nums[j]-dp[i]);}
        return dp[0]>=0;
    }
}
